variable "greeting" {
  description = "Message the app shows at /. Empty means the app's own default."
  type        = string
  default     = ""
}

variable "host_port" {
  description = "Port on your laptop that forwards to the app."
  type        = number
  default     = 8080

  validation {
    condition     = var.host_port >= 1024 && var.host_port <= 65535
    error_message = "host_port must be between 1024 and 65535."
  }
}

# A private network, so the app can reach Redis by its name (Day 14).
resource "docker_network" "app" {
  name = "hello-net"
}

resource "docker_image" "redis" {
  name         = "redis:8-alpine"
  keep_locally = true # Compose uses this image too, so never delete it
}

resource "docker_container" "redis" {
  name  = "hello-redis"
  image = docker_image.redis.image_id

  networks_advanced {
    name = docker_network.app.name
  }
}

locals {
  # Settings for the app. GREETING is only added when you set one.
  app_env = merge(
    {
      REDIS_HOST  = docker_container.redis.name
      APP_VERSION = var.app_version
    },
    var.greeting == "" ? {} : { GREETING = var.greeting },
  )
}

resource "docker_container" "web" {
  name  = "hello-web"
  image = var.app_image
  # Turns {REDIS_HOST = "hello-redis", ...} into ["REDIS_HOST=hello-redis", ...].
  env = [for key, value in local.app_env : "${key}=${value}"]

  ports {
    internal = 8000
    external = var.host_port
  }

  networks_advanced {
    name = docker_network.app.name
  }
}

output "url" {
  description = "Open this in your browser."
  value       = "http://localhost:${var.host_port}"
}

output "containers" {
  description = "The containers this folder manages."
  value       = [docker_container.redis.name, docker_container.web.name]
}

# Day 26: count vs for_each. No Docker needed: these resources are plain files.
terraform {
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.9"
    }
  }
}

variable "names" {
  description = "One file per name, made twice: once with count, once with for_each."
  type        = list(string)
  default     = ["alpha", "bravo", "charlie"]
}

# count: copies are numbered 0, 1, 2. The number is the copy's identity.
resource "local_file" "by_count" {
  count    = length(var.names)
  filename = "${path.module}/out/count-${count.index}.txt"
  content  = "hello ${var.names[count.index]}\n"
}

# for_each: copies are named after each key. The key is the copy's identity.
resource "local_file" "by_each" {
  for_each = toset(var.names)
  filename = "${path.module}/out/each-${each.key}.txt"
  content  = "hello ${each.key}\n"
}

output "count_files" {
  value = local_file.by_count[*].filename
}

output "each_files" {
  value = { for name, file in local_file.by_each : name => file.filename }
}

# Day 26 hands-on: one nginx container per entry in a map, with for_each.
terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 4.6"
    }
  }
}

provider "docker" {}

variable "sites" {
  description = "One nginx site per entry: site name => port on your laptop."
  type        = map(number)
  default = {
    blue  = 8101
    green = 8102
    red   = 8103
  }

  validation {
    condition     = alltrue([for port in values(var.sites) : port >= 1024 && port <= 65535])
    error_message = "Every port must be between 1024 and 65535."
  }
}

resource "docker_image" "nginx" {
  name         = "nginx:1.30-alpine"
  keep_locally = true
}

resource "docker_container" "site" {
  for_each = var.sites

  name  = "site-${each.key}"
  image = docker_image.nginx.image_id

  ports {
    internal = 80
    external = each.value
  }

  # Replace nginx's welcome page with one that names the site.
  upload {
    file    = "/usr/share/nginx/html/index.html"
    content = "<h1>Hello from ${each.key}</h1>\n"
  }
}

output "urls" {
  description = "One URL per site."
  value       = { for name, port in var.sites : name => "http://localhost:${port}" }
}

