# Day 27 worked example: look inside state, rename with moved, adopt with import.
terraform {
  required_providers {
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 4.6"
    }
  }
}

provider "docker" {}

resource "docker_image" "nginx" {
  name         = "nginx:1.30-alpine"
  keep_locally = true
}

# This resource started life as docker_container.web.
resource "docker_container" "site" {
  name  = "state-web"
  image = docker_image.nginx.image_id

  ports {
    internal = 80
    external = 8111
  }
}

# Same container, new address. Terraform renames it in state, nothing is rebuilt.
moved {
  from = docker_container.web
  to   = docker_container.site
}

# A container someone started by hand, before Terraform knew about it:
#   docker run -d --name state-legacy -p 8112:80 nginx:1.30-alpine
#
# It was adopted with an import block like this one. After the apply that
# imported it, the block has no more work to do, so it was deleted.
#   import {
#     to = docker_container.legacy
#     id = "<the full ID from: docker inspect -f '{{.Id}}' state-legacy>"
#   }

resource "docker_container" "legacy" {
  name = "state-legacy"
  # Docker reports the image by the name used in `docker run`, so use the
  # name here too. The image ID would not match and force a replacement.
  image = docker_image.nginx.name

  ports {
    internal = 80
    external = 8112
  }

  # The Docker provider cannot read env or ports back from a running
  # container. Without this, the import plan says "must be replaced".
  lifecycle {
    ignore_changes = [env, ports]
  }
}

# A private network, so the app can reach Redis by its name (Day 14).
resource "docker_network" "app" {
  name = "hello-net"
}

resource "docker_image" "redis" {
  name         = "redis:8-alpine"
  keep_locally = true # Compose uses this image too, so never delete it
}

resource "docker_container" "redis" {
  name  = "hello-redis"
  image = docker_image.redis.image_id

  networks_advanced {
    name = docker_network.app.name
  }
}

locals {
  # Settings for the app. GREETING is only added when you set one.
  app_env = merge(
    {
      REDIS_HOST  = docker_container.redis.name
      APP_VERSION = var.app_version
    },
    var.greeting == "" ? {} : { GREETING = var.greeting },
  )
}

resource "docker_container" "app" {
  name  = "hello-web"
  image = var.app_image
  # Turns {REDIS_HOST = "hello-redis", ...} into ["REDIS_HOST=hello-redis", ...].
  env = [for key, value in local.app_env : "${key}=${value}"]

  ports {
    internal = 8000
    external = var.host_port
  }

  networks_advanced {
    name = docker_network.app.name
  }
}

# Day 27: this resource used to be called docker_container.web.
# The moved block tells Terraform it is the same container, so it is kept.
moved {
  from = docker_container.web
  to   = docker_container.app
}

output "url" {
  description = "Open this in your browser."
  value       = "http://localhost:${var.host_port}"
}

output "containers" {
  description = "The containers this folder manages."
  value       = [docker_container.redis.name, docker_container.app.name]
}

